fn r2_uses_five_bytes_and_matches_all_of_u_for_an_empty_password() {
    assert_key_and_user_entry(R2.as_bytes(), b"", R2_KEY);

    let ignored_length = R2.replace("/Length 40", "/Length 128");
    assert_key_and_user_entry(ignored_length.as_bytes(), b"", R2_KEY);
}

fn r3_rehashes_only_the_eight_key_bytes_for_length_64() {
    // pypdf AlgV4 で求めた /O、/U、鍵を使い、16 バイト全体を再ハッシュすると検出する。
    let dictionary = b"<< /Filter /Standard /V 2 /R 3 /Length 64 /P -4
        /O <808b6846e0e99aee3b4dec725c7deb74982fc6c0b56891fc8add0a28ba8cdfe2>
        /U <6a5ab84c371817650499ca0001d73d7228bf4e5e4e758a4164004e56fffa0108> >>";

    assert_key_and_user_entry(dictionary, b"user", b"\xb6\x33\xf3\x0b\x9f\xfd\x9d\x54");
}

fn r3_uses_five_bytes_for_v1_and_when_v2_omits_length() {
    // pypdf AlgV4 で求めた /O、/U、鍵。両方とも R3 の 50 回反復が必要。
    let v1 = "<< /Filter /Standard /V 1 /R 3 /P -4 /EncryptMetadata false
        /O <3c482162008fafcb228b7db3c43a1090bc5b56e9b1556e89fc0656fd291f4908>
        /U <d3b1553015c7d57ed4c8a35b0f084ee928bf4e5e4e758a4164004e56fffa0108> >>";
    let v2 = v1.replace("/V 1", "/V 2");
    let expected = b"\x01\x85\x6e\x76\xcd";

    assert_key_and_user_entry(v1.as_bytes(), b"user", expected);
    assert_key_and_user_entry(v2.as_bytes(), b"user", expected);
}

fn r4_matches_u_when_metadata_is_encrypted_by_default() {
    let dictionary = R4_CLEAR_METADATA
        .replace(" /EncryptMetadata false", "")
        .replace(
            "3250600e32dc6a8eae7dc501b5ba8e52",
            "e250eb5d8e3c3f343517acaccb13a1bb",
        );
    let expected = b"\x08\x7e\xdb\xc7\x0b\x1e\x23\x18\x0c\xdb\xf4\x85\xf8\x2f\x3a\xb3";

    assert_key_and_user_entry(dictionary.as_bytes(), b"user", expected);
}

fn unsigned_permissions_give_the_same_key_as_signed_permissions() {
    let unsigned = R4_CLEAR_METADATA.replace("/P -3392", "/P 4294963904");
    let encryption = encrypt(unsigned.as_bytes());
    let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
    let trailer = parse_trailer(TRAILER);
    let key = handler
        .derive_legacy_file_key(b"user", trailer.id())
        .expect("符号なし表記でも鍵を導出できる");

    assert_eq!(key.as_bytes(), R4_CLEAR_METADATA_KEY);
}

fn derives_the_same_key_when_only_the_changing_id_is_replaced() {
    let encryption = encrypt(R2.as_bytes());
    let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
    let trailer = parse_trailer(
        b"trailer << /Root 1 0 R /Size 6 /Encrypt 5 0 R
            /ID [<31415926535897932384626433832795> (updated)] >>",
    );
    let key = handler
        .derive_legacy_file_key(b"", trailer.id())
        .expect("更新後のトレイラでも鍵を導出できる");

    assert_eq!(key.as_bytes(), R2_KEY);
}

fn reports_a_missing_file_id_at_derivation() {
    let encryption = encrypt(R2.as_bytes());
    let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
    let trailer = parse_trailer(b"trailer << /Root 1 0 R /Size 6 /Encrypt 5 0 R >>");
    let error = handler
        .derive_legacy_file_key(b"", trailer.id())
        .expect_err("/ID が欠けていると鍵は導出できない");

    assert_eq!(error, LegacyFileKeyError::MissingFileId);
}

fn accepts_a_present_file_id_with_an_empty_permanent_entry() {
    let encryption = encrypt(R2.as_bytes());
    let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
    let trailer = parse_trailer(b"trailer << /Root 1 0 R /Size 6 /Encrypt 5 0 R /ID [<> ()] >>");
    let key = handler
        .derive_legacy_file_key(b"", trailer.id())
        .expect("空の永続 ID で鍵を導出できる");

    // 永続 ID が空の場合の鍵は pypdf AlgV4 で確認した。
    assert_eq!(key.as_bytes(), b"\xc1\xdc\xdc\xa0\x2b");
}

fn truncates_the_password_after_32_bytes() {
    let encryption = encrypt(R3);
    let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
    let trailer = parse_trailer(TRAILER);
    let long_password = [R3_PASSWORD.as_slice(), b"\x00\xffextra"].concat();
    let key = handler
        .derive_legacy_file_key(&long_password, trailer.id())
        .expect("32 バイト超の入力でも鍵を導出できる");

    assert_eq!(key.as_bytes(), R3_KEY);
}

fn reports_short_and_long_owner_entries_at_derivation() {
    let trailer = parse_trailer(TRAILER);
    for actual in [31, 33] {
        let dictionary = format!(
            "<< /Filter /Standard /V 1 /R 2 /P -4 /O <{}> /U () >>",
            "00".repeat(actual)
        );
        let encryption = encrypt(dictionary.as_bytes());
        let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
        let error = handler
            .derive_legacy_file_key(b"", trailer.id())
            .expect_err("/O が 32 バイト以外では鍵を導出できない");

        assert_eq!(
            error,
            LegacyFileKeyError::InvalidOwnerEntryLength { actual }
        );
    }
}

fn reports_r5_and_r6_as_outside_algorithm_2() {
    let trailer = parse_trailer(TRAILER);
    for revision in [5, 6] {
        let dictionary = format!(
            "<< /Filter /Standard /V 5 /R {revision} /P -4 /CF << >>
                /O () /U () /OE () /UE () /Perms () >>"
        );
        let encryption = encrypt(dictionary.as_bytes());
        let handler = encryption.as_standard().expect("標準ハンドラを取得できる");
        let error = handler
            .derive_legacy_file_key(b"", trailer.id())
            .expect_err("R5 と R6 は別のアルゴリズムを使う");

        assert_eq!(error, LegacyFileKeyError::UnsupportedRevision);
    }
}

let file_id = file_id.ok_or(LegacyFileKeyError::MissingFileId)?;
let owner_entry = self.owner_key();
// Algorithm 3 の /O は 32 バイトに整えたパスワードの暗号化結果。
let owner_entry = <&[u8; PADDED_PASSWORD_LEN]>::try_from(owner_entry).map_err(|_| {
    LegacyFileKeyError::InvalidOwnerEntryLength {
        actual: owner_entry.len(),
    }
})?;

let mut md5 = Md5::new();
md5.update(&padded_password(password));
md5.update(owner_entry);
md5.update(&self.permissions().bits().to_le_bytes());
md5.update(file_id.permanent());

if matches!(algorithm, StandardAlgorithm::V4R4 { .. }) && !self.encrypt_metadata() {
    md5.update(&CLEAR_METADATA_BYTES);
}

let mut key = LegacyFileKey {
    digest: md5.finalize(),
    length,
};
for _ in 0..rehash_count {
    key.digest = Md5::digest(key.as_bytes());
}
Ok(key)

pub struct LegacyFileKey {
    digest: [u8; DIGEST_LEN],
    length: KeyLength,
}

impl LegacyFileKey {
    /// ファイル暗号鍵をバイト列で返す。
    #[must_use]
    pub fn as_bytes(&self) -> &[u8] {
        &self.digest[..usize::from(self.length.bytes())]
    }
}

let length = algorithm.key_length();
if usize::from(length.bytes()) > DIGEST_LEN {
    return Err(LegacyFileKeyError::InvalidKeyLength { length });
}

let mut md5 = Md5::new();
md5.update(&padded_password(password));
md5.update(owner_entry);
md5.update(&self.permissions().bits().to_le_bytes());
md5.update(file_id.permanent());

if matches!(algorithm, StandardAlgorithm::V4R4 { .. }) && !self.encrypt_metadata() {
    md5.update(&CLEAR_METADATA_BYTES);
}

let mut key = LegacyFileKey {
    digest: md5.finalize(),
    length,
};
for _ in 0..rehash_count {
    key.digest = Md5::digest(key.as_bytes());
}
Ok(key)
